// HasReviewedJobs applies the HasEdge predicate on the "reviewed_jobs" edge.
func HasReviewedJobs() predicate.User {
	return predicate.User(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ReviewedJobsTable, ReviewedJobsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReviewedJobsWith applies the HasEdge predicate on the "reviewed_jobs" edge with a given conditions (other predicates).
func HasReviewedJobsWith(preds ...predicate.JobPosting) predicate.User {
	return predicate.User(func(s *sql.Selector) {
		step := newReviewedJobsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

